<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {api} from '../lib/api'
import {useArcade} from '../stores/arcade'
import {useMessages} from '../stores/messages'
const sentDialog=ref(null),sentMessage=ref(''),pane=ref('write');const s=useArcade(),badges=useMessages(),data=ref({friends:[],items:[]}),login=ref(''),found=ref(null),searched=ref(false),error=ref(''),notice=ref(''),busy=ref(false),opened=ref(null),recipient=ref(''),title=ref(''),content=ref('');let timer,key=crypto.randomUUID(),loadSequence=0,alive=true
async function load(){const sequence=++loadSequence;try{const result=await api('/friends');if(alive&&sequence===loadSequence){data.value=result;await badges.refresh()}}catch(e){if(alive&&sequence===loadSequence)error.value=e.message}}
async function act(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function search(){act(async()=>{found.value=(await api('/friends/search?login='+encodeURIComponent(login.value))).student;searched.value=true})}
function add(id){act(async()=>{data.value=await api('/friends',{method:'POST',body:{studentId:id}});const accepted=data.value.friends.find(f=>f.id===id)?.accepted;sentMessage.value=accepted?'친구가 되었어요! 이제 쪽지를 보낼 수 있어요.':'친구 추가 요청을 보냈어요! 상대가 수락하면 쪽지를 보낼 수 있어요.';notice.value=sentMessage.value;sentDialog.value.showModal()})}
function open(id){act(async()=>{pane.value='write';opened.value=await api('/friend-messages/'+id+'/read',{method:'POST'});await load()})}
function send(){act(async()=>{await api('/friend-messages',{method:'POST',body:{recipient:recipient.value,title:title.value,content:content.value,requestKey:key}});key=crypto.randomUUID();title.value='';content.value='';notice.value='쪽지를 보냈어요!';await load()})}
function remove(id){if(!window.confirm('내 쪽지함에서 삭제할까요? 상대방의 쪽지는 유지됩니다.'))return;act(async()=>{await api('/friend-messages/'+id,{method:'DELETE'});if(opened.value?.id===id)opened.value=null;notice.value='내 쪽지함에서 삭제했어요.';await load()})}
function clearAll(){if(!window.confirm('내 친구 쪽지를 모두 삭제할까요? 친구 목록과 상대방의 쪽지는 유지됩니다.'))return;act(async()=>{await api('/friend-messages',{method:'DELETE',body:{confirmed:true}});opened.value=null;notice.value='친구 쪽지를 모두 삭제했어요.';await load()})}
function reply(){recipient.value=opened.value.sender;title.value='Re: '+opened.value.title;opened.value=null}
onMounted(()=>{window.addEventListener('spokemon-friends-refresh',load);load();timer=setInterval(load,15000)});onUnmounted(()=>{window.removeEventListener('spokemon-friends-refresh',load);alive=false;loadSequence++;clearInterval(timer)})
</script>
<template><section class="friend-inbox"><dialog ref="sentDialog" class="friend-sent-dialog" aria-label="친구 요청 전송 완료"><h2>친구 요청</h2><p>{{sentMessage}}</p><button @click="sentDialog.close()">확인</button></dialog><p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><div class="friend-mobile-tabs" aria-label="쪽지함 영역"><button :class="{selected:pane==='friends'}" @click="pane='friends'">친구 찾기</button><button :class="{selected:pane==='write'}" @click="pane='write'">쪽지 쓰기</button><button :class="{selected:pane==='list'}" @click="pane='list'">받고 보낸 쪽지</button></div><div :class="['friend-layout','pane-'+pane]"><aside class="panel friend-sidebar"><h2>내 친구</h2><form @submit.prevent="search"><label for="friend-search">친구 아이디 검색</label><div class="friend-search"><input id="friend-search" v-model="login" required minlength="3" maxlength="20" placeholder="정확한 아이디"/><button :disabled="busy">검색</button></div></form><div v-if="found" class="friend-row"><span>{{found.name}} · {{found.login}}</span><button :disabled="busy||data.friends.some(f=>f.id===found.id)" @click="add(found.id)">친구 추가</button></div><p v-else-if="searched">해당 아이디의 학생이 없어요.</p><p v-if="!data.friends.length">아이디를 검색해 친구를 추가하세요.</p><div v-for="f in data.friends" :key="f.id" class="friend-row"><span>{{f.name}} <small>@{{f.login}}</small></span><button v-if="!f.accepted&&f.sender!==s.user.id" :disabled="busy" @click="add(f.id)">수락</button><small v-else-if="!f.accepted">수락 대기</small><button v-else @click="recipient=f.id;opened=null;pane='write'">쪽지 쓰기</button></div></aside><div class="friend-main"><section v-if="opened" class="panel friend-reader"><button class="text-button" @click="opened=null">← 목록</button><button class="text-button mail-delete" :disabled="busy" @click="remove(opened.id)">쪽지 삭제</button><h2>{{opened.title}}</h2><p>{{opened.sender_name}} → {{opened.recipient_name}} · {{new Date(opened.created_at).toLocaleString('ko-KR')}}</p><p class="mail-body">{{opened.body}}</p><small>{{opened.read_at?'읽음':'읽지 않음'}}</small><button v-if="opened.sender!==s.user.id" @click="reply">답장 쓰기</button></section><form v-else class="panel friend-compose" @submit.prevent="send"><h2>친구에게 쪽지 쓰기</h2><label>받는 친구<select v-model="recipient" required><option disabled value="">친구 선택</option><option v-for="f in data.friends.filter(f=>f.accepted)" :key="f.id" :value="f.id">{{f.name}} · {{f.login}}</option></select></label><label>제목<input v-model="title" required maxlength="100"/></label><label>내용<textarea v-model="content" required maxlength="5000" rows="4"/></label><button :disabled="busy||!recipient||!title.trim()||!content.trim()">{{busy?'전송 중…':'쪽지 보내기'}}</button></form><section class="panel friend-mail-list"><div class="mailbox-heading"><h2>받고 보낸 쪽지</h2><button class="light mail-clear-all" :disabled="busy||!data.items.length" @click="clearAll">친구 쪽지 전체 삭제</button></div><p v-if="!data.items.length">친구와 주고받은 쪽지가 없어요.</p><div v-for="m in data.items" :key="m.id" class="friend-message-item"><button class="friend-mail-row" @click="open(m.id)"><span>{{m.sender===s.user.id?'보냄 → '+m.recipient_name:'받음 · '+m.sender_name}} <b v-if="m.recipient===s.user.id&&!m.read_at">NEW</b></span><strong>{{m.title}}</strong><small>{{new Date(m.created_at).toLocaleString('ko-KR')}} · {{m.read_at?'읽음':'읽지 않음'}}</small></button><button class="text-button mail-delete" :disabled="busy" @click="remove(m.id)">삭제</button></div></section></div></div></section></template>

<style scoped>.friend-sent-dialog{box-sizing:border-box;width:min(420px,calc(100vw - 30px));max-height:85dvh;padding:24px;background:var(--rpg-paper);color:var(--rpg-ink);border:3px solid var(--rpg-edge);border-radius:14px;text-align:center}.friend-sent-dialog::backdrop{background:#15233799}.friend-sent-dialog p{font-size:13px}</style>
